-- PostgreSQL replacement for MySQL ON UPDATE CURRENT_TIMESTAMP

CREATE OR REPLACE FUNCTION set_diperbarui_pada()
RETURNS trigger AS $$
BEGIN
  NEW.diperbarui_pada = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

