-- Tambahan kompatibilitas halaman legacy/performance.
-- Patch PostgreSQL untuk menampilkan data pada semua halaman aplikasi.
-- Aman dijalankan berulang karena memakai IF NOT EXISTS dan ON CONFLICT DO NOTHING.

CREATE OR REPLACE FUNCTION set_diperbarui_pada()
RETURNS TRIGGER AS $$
BEGIN
  NEW.diperbarui_pada = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE IF NOT EXISTS tim_kinerja (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama VARCHAR(150) NOT NULL,
  jenis VARCHAR(20) NOT NULL,
  aktif SMALLINT NOT NULL DEFAULT 1,
  dibuat_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_tim_kinerja_jenis_nama UNIQUE (jenis, nama)
);

CREATE TABLE IF NOT EXISTS master_kegiatan_kinerja (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama VARCHAR(180) NOT NULL,
  tipe_aktivitas VARCHAR(30) NOT NULL DEFAULT 'kegiatan',
  aktif SMALLINT NOT NULL DEFAULT 1,
  dibuat_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_master_kegiatan_kinerja_nama UNIQUE (nama)
);

CREATE TABLE IF NOT EXISTS penugasan_kinerja (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  pegawai_id INTEGER NOT NULL,
  tim_provinsi_id INTEGER DEFAULT NULL,
  tim_kabupaten_id INTEGER DEFAULT NULL,
  kegiatan_id INTEGER DEFAULT NULL,
  nama_aktivitas VARCHAR(200) NOT NULL,
  deskripsi TEXT DEFAULT NULL,
  label_prioritas VARCHAR(50) DEFAULT NULL,
  tahun INTEGER NOT NULL,
  bulan SMALLINT NOT NULL,
  tanggal_mulai DATE NOT NULL,
  tanggal_selesai DATE NOT NULL,
  tipe_aktivitas VARCHAR(30) NOT NULL DEFAULT 'kegiatan',
  satuan_target VARCHAR(60) NOT NULL,
  nilai_target NUMERIC(10,2) NOT NULL,
  nilai_realisasi NUMERIC(10,2) NOT NULL DEFAULT 0.00,
  bukti_realisasi TEXT DEFAULT NULL,
  status_submit VARCHAR(30) NOT NULL DEFAULT 'Belum Submit',
  aktif SMALLINT NOT NULL DEFAULT 1,
  dibuat_oleh_pegawai_id INTEGER DEFAULT NULL,
  dibuat_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  diperbarui_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS logbook_kinerja_harian (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  pegawai_id INTEGER NOT NULL,
  penugasan_id INTEGER DEFAULT NULL,
  tanggal DATE NOT NULL,
  jam_kerja NUMERIC(4,2) NOT NULL DEFAULT 0.00,
  status_hari VARCHAR(20) NOT NULL DEFAULT 'kerja',
  ringkasan TEXT NOT NULL,
  dibuat_oleh_pegawai_id INTEGER DEFAULT NULL,
  dibuat_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  diperbarui_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS kinerja_activity_histories (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  activity_id INTEGER NOT NULL,
  pegawai_id INTEGER DEFAULT NULL,
  action VARCHAR(40) NOT NULL,
  old_status VARCHAR(32) DEFAULT NULL,
  new_status VARCHAR(32) DEFAULT NULL,
  old_value TEXT DEFAULT NULL,
  new_value TEXT DEFAULT NULL,
  note TEXT DEFAULT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE kinerja_logbook ADD COLUMN IF NOT EXISTS started_at TIMESTAMP NULL;
ALTER TABLE kinerja_logbook ADD COLUMN IF NOT EXISTS paused_at TIMESTAMP NULL;
ALTER TABLE kinerja_logbook ADD COLUMN IF NOT EXISTS resumed_at TIMESTAMP NULL;
ALTER TABLE kinerja_logbook ADD COLUMN IF NOT EXISTS finished_at TIMESTAMP NULL;
ALTER TABLE kinerja_logbook ADD COLUMN IF NOT EXISTS total_paused_seconds INTEGER NOT NULL DEFAULT 0;
ALTER TABLE kinerja_logbook ADD COLUMN IF NOT EXISTS status_aktivitas VARCHAR(32) NULL;
ALTER TABLE kinerja_logbook ADD COLUMN IF NOT EXISTS last_activity_at TIMESTAMP NULL;

UPDATE kinerja_logbook
SET status_aktivitas = CASE
      WHEN status = 'dijeda' THEN 'jeda'
      WHEN status IN ('berjalan', 'jeda', 'selesai') THEN status
      ELSE COALESCE(status_aktivitas, 'selesai')
    END,
    last_activity_at = COALESCE(last_activity_at, diperbarui_pada, dibuat_pada)
WHERE status_aktivitas IS NULL OR last_activity_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_penugasan_kinerja_periode ON penugasan_kinerja (tahun, bulan, status_submit);
CREATE INDEX IF NOT EXISTS idx_penugasan_kinerja_pegawai ON penugasan_kinerja (pegawai_id);
CREATE INDEX IF NOT EXISTS idx_penugasan_kinerja_kegiatan ON penugasan_kinerja (kegiatan_id);
CREATE INDEX IF NOT EXISTS idx_penugasan_kinerja_tim_provinsi ON penugasan_kinerja (tim_provinsi_id);
CREATE INDEX IF NOT EXISTS idx_penugasan_kinerja_tim_kabupaten ON penugasan_kinerja (tim_kabupaten_id);
CREATE INDEX IF NOT EXISTS idx_logbook_kinerja_periode ON logbook_kinerja_harian (tanggal, pegawai_id);
CREATE INDEX IF NOT EXISTS idx_logbook_kinerja_penugasan ON logbook_kinerja_harian (penugasan_id);
CREATE INDEX IF NOT EXISTS idx_kinerja_activity_histories_activity ON kinerja_activity_histories (activity_id, created_at);
CREATE INDEX IF NOT EXISTS idx_kinerja_activity_histories_pegawai ON kinerja_activity_histories (pegawai_id, created_at);
CREATE INDEX IF NOT EXISTS idx_kinerja_logbook_timer_status ON kinerja_logbook (pegawai_id, status, assignment_id);
CREATE INDEX IF NOT EXISTS idx_kinerja_logbook_activity_status ON kinerja_logbook (pegawai_id, status_aktivitas, assignment_id, last_activity_at);

DROP TRIGGER IF EXISTS trg_penugasan_kinerja_diperbarui_pada ON penugasan_kinerja;
CREATE TRIGGER trg_penugasan_kinerja_diperbarui_pada
BEFORE UPDATE ON penugasan_kinerja
FOR EACH ROW EXECUTE FUNCTION set_diperbarui_pada();

DROP TRIGGER IF EXISTS trg_logbook_kinerja_harian_diperbarui_pada ON logbook_kinerja_harian;
CREATE TRIGGER trg_logbook_kinerja_harian_diperbarui_pada
BEFORE UPDATE ON logbook_kinerja_harian
FOR EACH ROW EXECUTE FUNCTION set_diperbarui_pada();

ON CONFLICT (jenis, nama) DO NOTHING;

ON CONFLICT (nama) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('tim_kinerja','id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM tim_kinerja), 1), true);
SELECT setval(pg_get_serial_sequence('master_kegiatan_kinerja','id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM master_kegiatan_kinerja), 1), true);
SELECT setval(pg_get_serial_sequence('penugasan_kinerja','id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM penugasan_kinerja), 1), true);
SELECT setval(pg_get_serial_sequence('logbook_kinerja_harian','id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM logbook_kinerja_harian), 1), true);

COMMIT;
